-- ============================================================================
-- Hosil Platform Database Migration: V13
-- Description: Logistics shipment requests and auditable status history (Milestone 6B.11)
-- Companion Reference: docs/04_domain_model.md §4.5 (Tables 28 & 30), LOG-001 - LOG-009
-- ============================================================================

-- 1. Table: shipment_requests (Transport requests generated by farmers, buyers, or commercial sellers)
CREATE TABLE IF NOT EXISTS shipment_requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    request_number VARCHAR(50) NOT NULL,
    requester_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    order_id UUID REFERENCES orders(id) ON DELETE RESTRICT,
    harvest_batch_id UUID REFERENCES harvest_batches(id) ON DELETE RESTRICT,
    cargo_description VARCHAR(255) NOT NULL,
    cargo_weight_kg NUMERIC(10, 2) NOT NULL,
    cargo_volume_m3 NUMERIC(10, 2),
    cargo_type VARCHAR(100),
    vehicle_requirements VARCHAR(100),
    origin_region VARCHAR(100) NOT NULL,
    origin_district VARCHAR(100) NOT NULL,
    origin_address TEXT,
    origin_contact_name VARCHAR(150),
    origin_contact_phone VARCHAR(50),
    destination_region VARCHAR(100) NOT NULL,
    destination_district VARCHAR(100) NOT NULL,
    destination_address TEXT,
    destination_contact_name VARCHAR(150),
    destination_contact_phone VARCHAR(50),
    pickup_window_start TIMESTAMPTZ NOT NULL,
    pickup_window_end TIMESTAMPTZ NOT NULL,
    delivery_deadline TIMESTAMPTZ,
    special_instructions TEXT,
    status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED',
    assigned_carrier_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    cancellation_reason TEXT,
    idempotency_key VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_shipment_requests_number UNIQUE (request_number),
    CONSTRAINT chk_shipment_requests_weight CHECK (cargo_weight_kg > 0),
    CONSTRAINT chk_shipment_requests_window CHECK (pickup_window_end >= pickup_window_start),
    CONSTRAINT chk_shipment_requests_status CHECK (status IN (
        'REQUESTED', 'QUOTED', 'ACCEPTED', 'PICKUP_ARRANGED', 'PICKED_UP', 'IN_TRANSIT', 'DELIVERED', 'CANCELLED', 'EXPIRED'
    ))
);

-- Indexes for shipment_requests
CREATE INDEX IF NOT EXISTS idx_shipment_requests_requester ON shipment_requests(requester_user_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_shipment_requests_order ON shipment_requests(order_id);
CREATE INDEX IF NOT EXISTS idx_shipment_requests_harvest_batch ON shipment_requests(harvest_batch_id);
CREATE INDEX IF NOT EXISTS idx_shipment_requests_active ON shipment_requests(origin_region, destination_region, status)
    WHERE status IN ('REQUESTED', 'QUOTED');
CREATE INDEX IF NOT EXISTS idx_shipment_requests_carrier ON shipment_requests(assigned_carrier_user_id)
    WHERE assigned_carrier_user_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_shipment_requests_idempotency ON shipment_requests(requester_user_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL;

-- 2. Table: shipment_status_history (Auditable chronological status timeline per LOG-006, LOG-009)
CREATE TABLE IF NOT EXISTS shipment_status_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    shipment_request_id UUID NOT NULL REFERENCES shipment_requests(id) ON DELETE CASCADE,
    from_status VARCHAR(30),
    to_status VARCHAR(30) NOT NULL,
    actor_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    actor_role VARCHAR(50),
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_shipment_status_history_req ON shipment_status_history(shipment_request_id, created_at ASC);
